package com.noteforge.platform.service;

import com.noteforge.platform.dto.ApiResponse;
import com.noteforge.platform.dto.LoginRequest;
import com.noteforge.platform.entity.User;
import com.noteforge.platform.mapper.UserMapper;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

@Service
public class AuthService {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private long expiration;

    private final UserMapper userMapper;

    public AuthService(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    public ApiResponse<Map<String, Object>> login(LoginRequest request) {
        User user = userMapper.selectByUsername(request.getUsername());
        if (user == null || !Objects.equals(user.getPassword(), request.getPassword())) {
            return ApiResponse.error(401, "用户名或密码错误");
        }
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("token", generateToken(user));
        data.put("username", user.getUsername());
        data.put("role", user.getRole());
        return ApiResponse.success("登录成功", data);
    }

    private String generateToken(User user) {
        SecretKey key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        return Jwts.builder()
                .claim("userId", user.getId())
                .claim("username", user.getUsername())
                .claim("role", user.getRole())
                .issuedAt(new Date())
                .expiration(new Date(System.currentTimeMillis() + expiration))
                .signWith(key)
                .compact();
    }
}

package com.noteforge.platform.service;

import com.noteforge.platform.dto.ApiResponse;
import com.noteforge.platform.dto.LinkPreviewRequest;
import com.noteforge.platform.entity.LinkPreview;
import com.noteforge.platform.mapper.LinkPreviewMapper;
import org.springframework.stereotype.Service;

import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Service
public class LinkPreviewService {

    private static final int TIMEOUT_MILLIS = 10000;

    private static final Pattern TITLE_PATTERN =
            Pattern.compile("<title[^>]*>(.*?)</title>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern META_TAG_PATTERN =
            Pattern.compile("<meta\\b[^>]*>", Pattern.CASE_INSENSITIVE);
    private static final Pattern LINK_TAG_PATTERN =
            Pattern.compile("<link\\b[^>]*>", Pattern.CASE_INSENSITIVE);

    private final LinkPreviewMapper linkPreviewMapper;

    public LinkPreviewService(LinkPreviewMapper linkPreviewMapper) {
        this.linkPreviewMapper = linkPreviewMapper;
    }

    public ApiResponse<LinkPreview> preview(Long userId, LinkPreviewRequest request) {
        String url = request.getUrl();
        if (url == null || !(url.startsWith("http://") || url.startsWith("https://"))) {
            return ApiResponse.error(400, "URL必须以http://或https://开头");
        }
        LinkPreview preview = new LinkPreview();
        preview.setUrl(url);
        preview.setOwnerId(userId);
        preview.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));

        HttpURLConnection connection = null;
        boolean retrieved = false;
        try {
            connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(TIMEOUT_MILLIS);
            connection.setReadTimeout(TIMEOUT_MILLIS);
            connection.setInstanceFollowRedirects(true);
            int statusCode = connection.getResponseCode();
            InputStream stream = statusCode >= 400 ? connection.getErrorStream() : connection.getInputStream();
            if (stream == null) {
                stream = connection.getErrorStream();
            }
            String body = stream == null ? "" : new String(stream.readAllBytes(), StandardCharsets.UTF_8);
            preview.setTitle(extractTitle(body));
            preview.setDescription(extractMetaDescription(body));
            preview.setFaviconUrl(extractFaviconUrl(body));
            retrieved = true;
        } catch (Exception e) {
            preview.setTitle(null);
            preview.setDescription(null);
            preview.setFaviconUrl(null);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
        linkPreviewMapper.insert(preview);
        return retrieved
                ? ApiResponse.success("预览生成成功", preview)
                : ApiResponse.success("预览生成失败", preview);
    }

    public ApiResponse<List<LinkPreview>> list(Long userId) {
        return ApiResponse.success(linkPreviewMapper.selectByOwnerId(userId));
    }

    private String extractTitle(String html) {
        if (html == null) {
            return null;
        }
        Matcher matcher = TITLE_PATTERN.matcher(html);
        return matcher.find() ? matcher.group(1).trim() : null;
    }

    private String extractMetaDescription(String html) {
        if (html == null) {
            return null;
        }
        Matcher tagMatcher = META_TAG_PATTERN.matcher(html);
        while (tagMatcher.find()) {
            String tag = tagMatcher.group();
            String name = extractAttribute(tag, "name");
            if (name != null && name.equalsIgnoreCase("description")) {
                String content = extractAttribute(tag, "content");
                if (content != null) {
                    return content;
                }
            }
        }
        return null;
    }

    private String extractFaviconUrl(String html) {
        if (html == null) {
            return null;
        }
        Matcher tagMatcher = LINK_TAG_PATTERN.matcher(html);
        while (tagMatcher.find()) {
            String tag = tagMatcher.group();
            String rel = extractAttribute(tag, "rel");
            if (rel != null && (rel.equalsIgnoreCase("icon") || rel.equalsIgnoreCase("shortcut icon"))) {
                String href = extractAttribute(tag, "href");
                if (href != null) {
                    return href;
                }
            }
        }
        return null;
    }

    private String extractAttribute(String tag, String attributeName) {
        Matcher matcher = Pattern.compile("\\b" + attributeName + "\\s*=\\s*([\"'])(.*?)\\1", Pattern.CASE_INSENSITIVE)
                .matcher(tag);
        return matcher.find() ? matcher.group(2).trim() : null;
    }
}

package com.noteforge.platform.service;

import com.noteforge.platform.dto.ApiResponse;
import com.noteforge.platform.dto.NoteCreateRequest;
import com.noteforge.platform.dto.NoteUpdateRequest;
import com.noteforge.platform.entity.Note;
import com.noteforge.platform.mapper.NoteMapper;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;

@Service
public class NoteService {

    private final NoteMapper noteMapper;

    public NoteService(NoteMapper noteMapper) {
        this.noteMapper = noteMapper;
    }

    public ApiResponse<Note> create(Long userId, NoteCreateRequest request) {
        Note note = new Note();
        note.setTitle(request.getTitle());
        note.setContent(request.getContent());
        note.setAuthorId(userId);
        note.setIsPublic(request.getIsPublic() != null && request.getIsPublic());
        note.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        note.setUpdatedAt(null);
        noteMapper.insert(note);
        return ApiResponse.success("创建成功", note);
    }

    public ApiResponse<List<Note>> list(Long userId) {
        return ApiResponse.success(noteMapper.selectVisibleByUserId(userId));
    }

    public ApiResponse<Note> detail(Long userId, Long id) {
        Note note = noteMapper.selectById(id);
        if (note == null) {
            return ApiResponse.error(404, "笔记不存在");
        }
        if (!note.getAuthorId().equals(userId) && !Boolean.TRUE.equals(note.getIsPublic())) {
            return ApiResponse.error(403, "无权查看此笔记");
        }
        return ApiResponse.success(note);
    }

    public ApiResponse<Note> update(Long userId, Long id, NoteUpdateRequest request) {
        Note note = noteMapper.selectById(id);
        if (note == null) {
            return ApiResponse.error(404, "笔记不存在");
        }
        if (!note.getAuthorId().equals(userId)) {
            return ApiResponse.error(403, "无权更新此笔记");
        }
        if (request.getTitle() != null) {
            note.setTitle(request.getTitle());
        }
        if (request.getContent() != null) {
            note.setContent(request.getContent());
        }
        if (request.getIsPublic() != null) {
            note.setIsPublic(request.getIsPublic());
        }
        note.setUpdatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        noteMapper.update(note);
        return ApiResponse.success("更新成功", note);
    }

    public ApiResponse<Void> delete(Long userId, String role, Long id) {
        Note note = noteMapper.selectById(id);
        if (note == null) {
            return ApiResponse.error(404, "笔记不存在");
        }
        if (!note.getAuthorId().equals(userId) && !"ADMIN".equals(role)) {
            return ApiResponse.error(403, "无权删除此笔记");
        }
        noteMapper.deleteById(id);
        return ApiResponse.success("删除成功", null);
    }
}

package com.noteforge.platform.service;

import com.noteforge.platform.dto.ApiResponse;
import com.noteforge.platform.dto.ResourceFetchRequest;
import com.noteforge.platform.entity.Resource;
import com.noteforge.platform.mapper.ResourceMapper;
import org.springframework.stereotype.Service;

import java.net.HttpURLConnection;
import java.net.URL;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;

@Service
public class ResourceService {

    private static final int TIMEOUT_MILLIS = 10000;

    private final ResourceMapper resourceMapper;

    public ResourceService(ResourceMapper resourceMapper) {
        this.resourceMapper = resourceMapper;
    }

    public ApiResponse<Resource> fetch(Long userId, ResourceFetchRequest request) {
        String url = request.getUrl();
        if (url == null || !(url.startsWith("http://") || url.startsWith("https://"))) {
            return ApiResponse.error(400, "URL必须以http://或https://开头");
        }
        Resource resource = new Resource();
        resource.setOriginalUrl(url);
        resource.setOwnerId(userId);
        resource.setNoteId(request.getNoteId());
        resource.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));

        HttpURLConnection connection = null;
        try {
            connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(TIMEOUT_MILLIS);
            connection.setReadTimeout(TIMEOUT_MILLIS);
            connection.setInstanceFollowRedirects(true);
            int statusCode = connection.getResponseCode();
            String contentType = connection.getContentType();
            long contentLength = connection.getContentLengthLong();
            resource.setStatusCode(statusCode);
            resource.setContentType(contentType);
            resource.setContentLength(contentLength < 0 ? 0L : contentLength);
            resource.setStatus("SUCCESS");
        } catch (Exception e) {
            resource.setStatus("FAILED");
            String message = e.getMessage();
            resource.setErrorMessage(message == null || message.isBlank() ? "连接超时" : message);
            resource.setContentLength(0L);
            resource.setContentType(null);
            resource.setStatusCode(null);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
        resourceMapper.insert(resource);
        return "SUCCESS".equals(resource.getStatus())
                ? ApiResponse.success("资源获取成功", resource)
                : ApiResponse.success("资源获取失败", resource);
    }

    public ApiResponse<List<Resource>> list(Long userId) {
        return ApiResponse.success(resourceMapper.selectByOwnerId(userId));
    }
}

package com.noteforge.platform.service;

import groovy.lang.GroovyShell;
import org.springframework.stereotype.Service;

@Service
public class ScriptSandboxService {

    public Object evaluateScript(String script) {
        if (script == null || script.isBlank()) {
            throw new IllegalArgumentException("script must not be null or blank");
        }
        try {
            return new GroovyShell().evaluate(script);
        } catch (RuntimeException e) {
            throw new RuntimeException("script evaluation failed: " + e.getMessage(), e);
        }
    }
}

package com.noteforge.platform.util;

import com.noteforge.platform.entity.User;
import com.noteforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;

    public DataInitializer(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() > 0) {
            return;
        }
        createUser("admin", "admin123", "ADMIN");
        createUser("user1", "user123", "USER");
        createUser("user2", "user456", "USER");
    }

    private void createUser(String username, String password, String role) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(password);
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        userMapper.insert(user);
    }
}
